package com.lemnt.mall.adapter.rpc;
import com.lemnt.mall.client.ProductCatalogClient;import com.lemnt.mall.client.dto.ProductSnapshotDTO;import com.lemnt.mall.domain.gateway.ProductGateway;import com.lemnt.mall.domain.model.Product;import lombok.RequiredArgsConstructor;import org.apache.dubbo.config.annotation.DubboService;
@DubboService @RequiredArgsConstructor public class ProductCatalogClientImpl implements ProductCatalogClient {private final ProductGateway gateway;public ProductSnapshotDTO findOnShelf(Long id){Product p=gateway.findById(id);return p==null||!"ON_SHELF".equals(p.status())?null:new ProductSnapshotDTO(p.id(),p.productCode(),p.name(),p.price(),p.stock());}public boolean reserveStock(Long id,Integer qty){return gateway.reserveStock(id,qty);}public void releaseStock(Long id,Integer qty){gateway.releaseStock(id,qty);}}